#pragma once
/*
 * Helpers for the JPEG and GIF tests: fixtures under tests/image/ (generated by
 * tests/image/make_fixtures.sh), reference decodes under tests/image/ref/ (PNG, decoded by the
 * built-in PNG decoder, which the PngSuite tests cover), and a per-channel comparison.
 */
#include "emb_test.h"

#include "base/base.h"
#include "image/image.h"
#include "image/png.h"

#include <SDL3/SDL_iostream.h>
#include <SDL3/SDL_stdinc.h>

/* Loads tests/image/<rel> (or any path under the source root). Returns nullptr on failure. */
static inline uint8_t *fx_load(const char *rel, size_t *len)
{
    char path[1024];
    SDL_snprintf(path, sizeof path, "%s/%s", EMBER_SOURCE_DIR, rel);
    *len = 0;
    return (uint8_t *)SDL_LoadFile(path, len);
}

/* Decodes tests/image/ref/<name>.png to straight RGBA8. The caller frees with embi_pixels_free. */
static inline bool fx_ref(const char *name, embi_pixels *out)
{
    char rel[256];
    SDL_snprintf(rel, sizeof rel, "tests/image/ref/%s.png", name);
    size_t len = 0;
    uint8_t *bytes = fx_load(rel, &len);
    if (!bytes) {
        return false;
    }
    bool ok = embi_png_decode(bytes, len, (uint64_t)1 << 30, false, out);
    SDL_free(bytes);
    return ok;
}

/* Per-channel comparison of two RGBA8 images of the same size. max_err is the largest channel
 * difference seen. over3 counts channel values that differ by more than 3. When rgb_masked is set,
 * the color channels of pixels that are fully transparent in ref are not compared (GIF leaves them
 * undefined); alpha is always compared. Returns false when the sizes differ. */
typedef struct fx_diff {
    int max_err;
    size_t over3;
    size_t channels;
} fx_diff;

static inline bool fx_compare(const embi_pixels *got, const embi_pixels *ref, bool rgb_masked,
                              fx_diff *d)
{
    d->max_err = 0;
    d->over3 = 0;
    d->channels = 0;
    if (got->w != ref->w || got->h != ref->h) {
        return false;
    }
    size_t n = (size_t)ref->w * ref->h;
    for (size_t i = 0; i < n; i++) {
        const uint8_t *g = got->px + i * 4;
        const uint8_t *r = ref->px + i * 4;
        bool skip_rgb = rgb_masked && r[3] == 0;
        for (int c = 0; c < 4; c++) {
            if (c < 3 && skip_rgb) {
                continue;
            }
            int diff = (int)g[c] - (int)r[c];
            if (diff < 0) {
                diff = -diff;
            }
            d->channels++;
            if (diff > d->max_err) {
                d->max_err = diff;
            }
            if (diff > 3) {
                d->over3++;
            }
        }
    }
    return true;
}
